package dev.cxo.filmpack.android

import android.test.AndroidTestCase
import android.util.Log
import dev.cxo.filmpack.core.FilmRgbBaseScaleCatalog
import dev.cxo.filmpack.core.LcmsOptimizedQ15Transform
import dev.cxo.filmpack.core.NativeWhiteBalanceRgb
import dev.cxo.filmpack.core.WhiteBalanceRgb
import java.io.DataInputStream

/**
 * Android-runtime replay of native-derived white-balance fixtures.
 *
 * These tests exercise Kotlin only. The saved values were generated by the
 * owned original-process probes described next to each fixture; this test does
 * not load or execute the original DxO libraries on Android.
 */
@Suppress("DEPRECATION")
class WhiteBalanceAndroidVerificationTest : AndroidTestCase() {
    fun testNativeColorAndTemperatureFactorsBitExactly() {
        val assets = context.assets
        val transform = assets.open("wb-factors/adobe-to-source-srgb.lcmsbin").use {
            LcmsOptimizedQ15Transform.read(it.readBytes())
        }
        DataInputStream(assets.open("wb-factors/validation.golden").buffered()).use { data ->
            fun int() = Integer.reverseBytes(data.readInt())
            fun float() = Float.fromBits(int())

            val magic = ByteArray(8).also { data.readFully(it) }
            check(magic.contentEquals("CXOWBV01".toByteArray(Charsets.US_ASCII)))
            val colorRows = int()
            val temperatureRows = int()
            check(colorRows == 5516 && temperatureRows == 270)

            repeat(colorRows) { row ->
                val input = FloatArray(3) { float() }
                val expected = FloatArray(3) { float() }
                val actual = WhiteBalanceRgb.colorFactors(input) { transform.convert(it) }
                for (channel in 0..2) {
                    check(actual[channel].toRawBits() == expected[channel].toRawBits()) {
                        "Color factor mismatch row $row channel $channel"
                    }
                }
            }
            repeat(temperatureRows) { row ->
                val temperature = float()
                val expected = FloatArray(3) { float() }
                val actual = WhiteBalanceRgb.temperatureFactors(temperature)
                for (channel in 0..2) {
                    check(actual[channel].toRawBits() == expected[channel].toRawBits()) {
                        "Temperature factor mismatch row $row channel $channel"
                    }
                }
            }
            check(data.read() == -1) { "Unexpected WB-factor fixture trailing bytes" }
            Log.i("WhiteBalanceAndroidVerification", "native_factor_rows=${colorRows + temperatureRows} components=${(colorRows + temperatureRows) * 3} exact=true")
        }
    }

    fun testCapturedWhiteBalanceToColorRenderingBoundaryExactly() {
        val assets = context.assets
        val catalog = assets.open("film-rgb-base/catalog.cxowbs").use { FilmRgbBaseScaleCatalog.read(it) }
        check(catalog.presets.size == 147)
        check(catalog.presets.count { !it.isIdentity } == 27)

        DataInputStream(assets.open("film-rgb-base/native-boundary.golden").buffered()).use { data ->
            fun int() = Integer.reverseBytes(data.readInt())
            fun short() = java.lang.Short.reverseBytes(data.readShort())

            val magic = ByteArray(8).also { data.readFully(it) }
            check(magic.contentEquals("CXOWBI01".toByteArray(Charsets.US_ASCII)))
            val films = int()
            check(films == 27)
            var samples = 0
            repeat(films) {
                val length = int()
                check(length in 1..160)
                val id = ByteArray(length).also { data.readFully(it) }.toString(Charsets.US_ASCII)
                val stage = NativeWhiteBalanceRgb.create(requireNotNull(catalog.find(id)))
                val rows = int()
                check(rows in 1..100000)
                val actual = IntArray(3)
                repeat(rows) { row ->
                    val source = IntArray(3) { short().toInt() }
                    val expected = IntArray(3) { short().toInt() }
                    stage.applyQ15(source[0], source[1], source[2], actual)
                    check(actual.contentEquals(expected)) { "WB boundary mismatch $id row $row" }
                }
                samples += rows
            }
            check(samples == 103707)
            check(data.read() == -1) { "Unexpected WB-boundary fixture trailing bytes" }
            Log.i("WhiteBalanceAndroidVerification", "native_boundary_films=$films q15_rgb_samples=$samples components=${samples * 3} exact=true")
        }
    }

    fun testNativeMultiplyConstant16sFixtureExactly() {
        DataInputStream(context.assets.open("wb-direct-kernel/native-kernel.golden").buffered()).use { data ->
            fun int() = Integer.reverseBytes(data.readInt())
            fun short() = java.lang.Short.reverseBytes(data.readShort())

            val magic = ByteArray(8).also { data.readFully(it) }
            check(magic.contentEquals("CXOWBI01".toByteArray(Charsets.US_ASCII)))
            val gainRows = int()
            check(gainRows == 11)
            var samples = 0
            repeat(gainRows) { row ->
                val gains = FloatArray(3) { Float.fromBits(int()) }
                val expectedShift = int()
                val expectedCoefficients = IntArray(3) { int() }
                val length = int()
                check(length in 1..100000)
                val source = ShortArray(length * 3) { short() }
                val expected = ShortArray(length * 3) { short() }
                val stage = NativeWhiteBalanceRgb.fromGains(gains[0], gains[1], gains[2])
                check(stage.commonShift == expectedShift) { "WB shift mismatch fixture row $row" }
                check(stage.integerCoefficients().contentEquals(expectedCoefficients)) {
                    "WB coefficients mismatch fixture row $row"
                }
                val actual = ShortArray(source.size)
                stage.applyQ15(source, actual)
                val alias = source.copyOf()
                stage.applyQ15(alias, alias)
                check(actual.contentEquals(expected)) { "WB bulk mismatch fixture row $row" }
                check(alias.contentEquals(expected)) { "WB in-place mismatch fixture row $row" }
                samples += length
            }
            check(samples == 451)
            check(data.read() == -1) { "Unexpected direct-kernel fixture trailing bytes" }
            Log.i("WhiteBalanceAndroidVerification", "native_direct_kernel_gain_rows=$gainRows q15_rgb_samples=$samples components=${samples * 3} exact=true")
        }
    }
}
